export default {
  props: {
    needSelect: {
      type: Boolean,
      default: true
    },
    needAction: {
      type: Boolean,
      default: false
    },
    actionWidth: {
      type: String,
      default: '150px'
    },
    ref: {
      type: String,
      default: 'table'
    },
    size: {
      type: String,
      default: 'small',
    },
    tableData: {
      type: Array,
      default: []
    },
    colList: {
      type: Array,
      default: []
    },
    tableHeight: {
      type: String,
      default: undefined
    },
    tableLoading: {
      type: Boolean,
      default: false
    }
  },
  data() {
    return {
      tableList: [],
      tableInit: false,
    }
  },
  watch: {
    colList: {
      deep: true,
      handler() {
        this.initData()
      },
    }
  },
  mounted() {
    // this.initData()
  },
  methods: {
    initData() {
      this.tableList = []
      this.tableInit = true
      this.tableData.forEach((item, index) => {
        let resRowData = Object.assign(item.attrEntityData, item.globalAttrEntityData)
        let rowData = {}
        // 设置行数据初始值
        this.colList.forEach(it => {
          rowData = item
          rowData[it.key] = '--'
        })

        for (let key in resRowData) {
          // let arrtType = key[]
          if (resRowData[key].valueList.length == 1 && typeof resRowData[key].valueList[0] != 'object') {
            rowData[key] = resRowData[key].actualValueList[0]
          } else {
            rowData[key] = resRowData[key].actualValueList
          }
        }
        this.tableList.push(rowData)
      })
      this.tableInit = false
      this.$nextTick(() => {
        this.$refs[this.ref].doLayout()
      })
    },
    rowDbClcik(row, column, event) {
      this.$emit('rowDbClcik', {row, column, event})
    },
    selectionChange(selection){
      this.$emit('selectionChange', selection)
    }
  }
}
